using SysAdminAssistant.Core;
using SysAdminAssistant.Infrastructure;
internal static class Revision129Specs
{
 static Dictionary<string,string> R(params string[] fields)=>fields.ToDictionary(s=>s[..s.IndexOf('=')],s=>s[(s.IndexOf('=')+1)..]);
 static RouterAuditConfig Fixture(){var c=new RouterAuditConfig();foreach(var key in RouterAuditReader.Commands.Keys)c.Tables[key]=[];c.Tables["interfaces"]=[R("name=uplink"),R("name=second"),R("name=inside")];c.Tables["lists"]=[R("name=WAN")];c.Tables["members"]=[R("list=WAN","interface=uplink"),R("list=WAN","interface=second")];c.Tables["addresses4"]=[R("address=198.51.100.2/24","interface=uplink"),R("address=198.51.100.3/24","interface=second"),R("address=10.23.0.1/24","interface=inside")];c.Tables["ipv6-settings"]=[R("disable-ipv6=yes")];c.Tables["mac"]=[R("allowed-interface-list=none")];c.Tables["mac-winbox"]=[R("allowed-interface-list=none")];c.Tables["neighbors"]=[R("discover-interface-list=none")];c.Tables["filter4"]=[R(".id=*F","chain=input","action=drop"),R(".id=*G","chain=forward","action=accept","connection-nat-state=dstnat")];c.Tables["nat4"]=[R(".id=*A","chain=dstnat","action=dst-nat","protocol=tcp","dst-port=34635","to-addresses=10.23.0.8","to-ports=3389","in-interface=uplink"),R(".id=*B","chain=dstnat","action=dst-nat","protocol=tcp","dst-port=34635","to-addresses=10.23.0.8","to-ports=3389","in-interface=second")];return c;}
 public static async Task Run(string folder,Action<string,bool> check){
  var c=Fixture();var result=RouterAudit.Analyze(c);var publication=result.Findings.Single(f=>f.Key.StartsWith("nat:"));check("Same NAT endpoint over two WAN rules has one card",publication.Evidence.Contains("вход uplink")&&publication.Evidence.Contains("вход second"));
  var key=publication.Key;c.Tables["nat4"][0][".id"]="*NEW";check("Publication identity survives RouterOS rule identifier change",RouterAudit.Analyze(c).Findings.Single(f=>f.Key.StartsWith("nat:")).Key==key);
  var directory=Path.Combine(folder,"persistent-audit-ignore");var store=new NetworkStore(directory);store.State(s=>{var h=new NetworkHistory{DeviceId=4};s.Histories.Add(h);RouterAuditStore.Apply(s,h,result,"fixture");return true;},true);var view=RouterAuditStore.View(store,4);RouterAuditStore.Ignore(store,new(4,key,publication.Fingerprint,true,view.Hash),"admin");
  c.Tables["filter4"].Insert(0,R(".id=*R","chain=forward","action=drop","src-address=203.0.113.10"));var changed=RouterAudit.Analyze(c);check("Ignore regression actually changes finding evidence",changed.Findings.Single(f=>f.Key==key).Fingerprint!=publication.Fingerprint);
  var reopened=new NetworkStore(directory);reopened.State(s=>{RouterAuditStore.Apply(s,s.Histories.Single(),changed,"fixture");return true;},true);view=RouterAuditStore.View(new NetworkStore(directory),4);check("Ignore survives storage reopen and changed report fingerprint",view.Result!.Findings.Single(f=>f.Key==key).Ignored);
  var current=view.Result!.Findings.Single(f=>f.Key==key);RouterAuditStore.Ignore(reopened,new(4,key,current.Fingerprint,false,view.Hash),"admin");reopened.State(s=>{RouterAuditStore.Apply(s,s.Histories.Single(),RouterAudit.Analyze(c),"fixture");return true;},true);check("Explicit unignore remains effective on next reread",!RouterAuditStore.View(reopened,4).Result!.Findings.Single(f=>f.Key==key).Ignored);
  var outbox=new NetworkStore(Path.Combine(folder,"concurrent-delivery"));outbox.State(s=>{s.Notifications.Add(new(){EntityKey="fixture",Severity=Severity.Critical,Title="fixture"});return true;},true);int sends=0;var settings=new TelegramSettings{Enabled=true,Critical=true,Warning=true,Info=true};
  Task Send(string _,CancellationToken token){Interlocked.Increment(ref sends);return Task.Delay(150,token);}
  await Task.WhenAll(NetworkNotifications.FlushAsync(outbox,settings,default,Send),NetworkNotifications.FlushAsync(new NetworkStore(outbox.DirectoryPath),settings,default,Send));check("Concurrent Telegram flush sends one queued message once",sends==1);
 }
